import unittest

from text import slugify


class SlugifyTests(unittest.TestCase):
    def test_basic_sentence(self):
        self.assertEqual(slugify("Hello, World!"), "hello-world")

    def test_collapses_whitespace_and_punctuation(self):
        self.assertEqual(slugify("  A --- Messy   Title!!  "), "a-messy-title")

    def test_strips_accents(self):
        self.assertEqual(slugify("Crème Brûlée"), "creme-brulee")

    def test_keeps_digits(self):
        self.assertEqual(slugify("Top 10 Receipts of 2026"), "top-10-receipts-of-2026")

    def test_already_slug_is_unchanged(self):
        self.assertEqual(slugify("already-a-slug"), "already-a-slug")

    def test_empty_string(self):
        self.assertEqual(slugify(""), "")

    def test_only_symbols_becomes_empty(self):
        self.assertEqual(slugify("!!!***???"), "")

    def test_non_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            slugify(None)


if __name__ == "__main__":
    unittest.main()

